    /// <inheritdoc />
    protected override async ValueTask<bool> RegisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case Graphic feature:
                if (feature != Feature)
                {
                    Feature = feature;
                    ModifiedParameters[nameof(Feature)] = Feature;
                }
                
                return true;
            case FormTemplate formTemplate:
                if (formTemplate != FormTemplate)
                {
                    FormTemplate = formTemplate;
                    ModifiedParameters[nameof(FormTemplate)] = FormTemplate;
                }
                
                return true;
            default:
                return await base.RegisterGeneratedChildComponent(child);
        }
    }

    /// <inheritdoc />
    protected override async ValueTask<bool> UnregisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case Graphic _:
                Feature = null;
                ModifiedParameters[nameof(Feature)] = Feature;
                return true;
            case FormTemplate _:
                FormTemplate = null;
                ModifiedParameters[nameof(FormTemplate)] = FormTemplate;
                return true;
            default:
                return await base.UnregisterGeneratedChildComponent(child);
        }
    }
    
    /// <inheritdoc />
    public override void ValidateRequiredGeneratedChildren()
    {
    
        Feature?.ValidateRequiredGeneratedChildren();
        FormTemplate?.ValidateRequiredGeneratedChildren();
        base.ValidateRequiredGeneratedChildren();
    }
      
